import heapq

def match(orders):
    buy_heap = []   # entries: (-price, arrival, id)
    sell_heap = []  # entries: (price, arrival, id)
    info = {}  # id -> [side, price, qty_remaining, arrival, alive]
    trades = []
    counter = 0

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in info and info[oid][4] and info[oid][2] > 0:
                info[oid][4] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        else:  # market
            _, oid, side, qty = order
            price = None

        arrival = counter
        counter += 1
        info[oid] = [side, price, qty, arrival, True]

        opp_heap = sell_heap if side == 'buy' else buy_heap

        remaining = qty

        while remaining > 0:
            # discard stale/invalid top entries
            while opp_heap:
                top = opp_heap[0]
                top_id = top[2]
                if (top_id not in info) or (not info[top_id][4]) or (info[top_id][2] <= 0):
                    heapq.heappop(opp_heap)
                else:
                    break

            if not opp_heap:
                break

            top = opp_heap[0]
            if side == 'buy':
                resting_price = top[0]
            else:
                resting_price = -top[0]

            if price is not None:
                if side == 'buy' and resting_price > price:
                    break
                if side == 'sell' and resting_price < price:
                    break

            resting_id = top[2]
            resting_qty = info[resting_id][2]
            trade_qty = min(remaining, resting_qty)

            if side == 'buy':
                trades.append([oid, resting_id, resting_price, trade_qty])
            else:
                trades.append([resting_id, oid, resting_price, trade_qty])

            remaining -= trade_qty
            info[resting_id][2] -= trade_qty
            info[oid][2] = remaining

            if info[resting_id][2] == 0:
                info[resting_id][4] = False
                heapq.heappop(opp_heap)

        info[oid][2] = remaining

        if typ == 'limit' and remaining > 0:
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, arrival, oid))
            else:
                heapq.heappush(sell_heap, (price, arrival, oid))
        else:
            info[oid][4] = False

    return trades

